const modal=document.createElement('div');modal.id='dossierEditModal';modal.className='modal dossier-modal';modal.innerHTML='<div class="dialog wide"><div class="dialoghead"><h2 id="dossierEditTitle"></h2><button class="close" onclick="closeModal(\'dossierEditModal\')">×</button></div><form id="dossierEditForm"><div class="dialogbody" id="dossierEditBody"></div><div class="dialogfoot"><button type="button" class="btn" onclick="closeModal(\'dossierEditModal\')">Abbrechen</button><button type="submit" class="btn primary">Speichern</button></div></form></div>';document.body.append(modal);
function dossierField(name,label,value='',type='text',required=false){return `<label>${DE(label)}<input class="field" name="${name}" type="${type}" value="${DE(value)}" ${required?'required':''}></label>`;}
function dossierChoicesField(name,label,value,choices){return `<label>${DE(label)}<input class="field" name="${name}" list="dossier-preset-${name}" value="${DE(value||'')}"><datalist id="dossier-preset-${name}">${choices.map(choice=>`<option value="${DE(choice)}"></option>`).join('')}</datalist></label>`;}
function dossierText(name,label,value='',required=false){return `<label class="full">${DE(label)}<textarea class="field" id="ds-${name}" name="${name}" ${required?'required':''}>${DE(value)}</textarea></label>`;}
function dossierNeutralText(value){let text=String(value||'').normalize('NFC').replace(/\r\n?/g,'\n').replace(/[ \t]{2,}/g,' ').replace(/[ \t]+([,.!?;:])/g,'$1').trim();const terms=[[/\bKids\b/gi,'Kinder'],[/\brumgeschrien\b/gi,'laut geschrien'],[/\babgehauen\b/gi,'weggelaufen'],[/\bZoff\b/gi,'Konflikt'],[/\bRückmledung\b/gi,'Rückmeldung'],[/\bElterngesparch\b/gi,'Elterngespräch']];for(const [from,to]of terms)text=text.replace(from,to);text=text.replace(/(^|[.!?]\s+|\n+)([a-zäöü])/g,(_all,begin,letter)=>begin+letter.toLocaleUpperCase('de'));return text.replace(/([^.!?\s])$/,'$1.');}
function dossierTextPreview(){const form=document.getElementById('dossierEditForm'),source=form.elements.content,box=document.getElementById('dossierTextPreview'),proposal=dossierNeutralText(source.value);if(!source.value.trim()){appAlert('Bitte zunächst einen Text eingeben.');return;}box.hidden=false;box.querySelector('textarea').value=proposal;box.querySelector('.dossier-text-original').textContent=source.value;box.querySelector('.dossier-text-result').textContent=proposal===source.value?'Keine sichere automatische Änderung gefunden. Der Text bleibt unverändert.':'Bitte alle Aussagen prüfen. Der Vorschlag wird erst nach deiner Auswahl und dem Speichern übernommen.';}
function dossierTextAccept(){const box=document.getElementById('dossierTextPreview');document.getElementById('dossierEditForm').elements.content.value=box.querySelector('textarea').value;box.hidden=true;}
function dossierOptions(values,selected){return values.map(v=>`<option ${v===selected?'selected':''}>${DE(v)}</option>`).join('');}
function dossierPopup(title,body,submit){document.getElementById('dossierEditTitle').textContent=title;document.getElementById('dossierEditBody').innerHTML=body;document.getElementById('dossierEditForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await submit(new FormData(e.target));}catch(err){appAlert(err.message||String(err));}finally{b.disabled=false;}};openModal('dossierEditModal');enhanceDictationFields();}
