async function dossierWorkflowChoose(eid,wid){const e=data.journal.find(x=>x.id===eid),w=WORKFLOWS.find(x=>x.id===wid);if(!e||!w||e.generalInfo||e.participantIds.length!==1)return;Dossier.editEntry(data,e,{workflowId:wid},data.settings.activeUser||'SSA');await dossierSave();dossierRefresh();}
function dossierCategory(e){
 const value=String(e.eventKind||e.type||e.taskType||'').toLocaleLowerCase('de');
 if(value.includes('fehlzeit'))return 'absence';
 if(value.includes('trainingsraum'))return 'training';
 if(/eltern|familie/.test(value))return 'parent';
 if(/externe|jugendamt|psycholog|netzwerk|bezugsperson/.test(value))return 'external';
 if(/dokument|bericht|formular|befund/.test(value))return 'document';
 if(e.task||/aufgabe|schritt|termin|überprüfung/.test(value))return 'task';
 if(/gespräch|kontakt|rückmeldung|beratung|gruppe|konflikt|abstimmung/.test(value))return 'talk';
 return 'neutral';
}
