function dossierSuggestions(e){requestAnimationFrame(()=>{const card=document.getElementById('ds-entry:'+e.id);card?.querySelector('.dossier-suggestions')?.setAttribute('open','');card?.scrollIntoView({block:'center'});});}
function dossierAbsenceFollowup(key,title){dossierEntry('response',key);const form=document.getElementById('dossierEditForm');form.elements.type.value='Rückmeldung';form.elements.title.value=title;form.elements.content.placeholder='Was ist tatsächlich geschehen? Datum, Kontaktweg und Ergebnis sachlich eintragen. Ohne Inhalt wird nichts gespeichert.';form.elements.content.focus();}
function dossierSuggestionFind(eid,sugid){const e=data.journal.find(e=>e.id===eid);return {e,s:e?.actionSuggestions?.find(s=>s.id===sugid)};}
async function dossierSuggestionIgnore(eid,sugid){const {s}=dossierSuggestionFind(eid,sugid);if(!s)return;s.status='nicht verwendet';s.decidedAt=new Date().toISOString();await dossierSave();dossierRefresh();}
async function dossierSuggestionRestore(eid,sugid){const {s}=dossierSuggestionFind(eid,sugid);if(!s)return;s.status='offen';delete s.decidedAt;await dossierSave();dossierRefresh();}
function dossierSuggestedDue(days){if(!Number.isInteger(days))return '';const date=new Date(today()+'T12:00:00');for(let i=0;i<days;){date.setDate(date.getDate()+1);if(date.getDay()!==0&&date.getDay()!==6)i++;}return date.toISOString().slice(0,10);}
function dossierSuggestionUse(eid,sugid){const {e,s}=dossierSuggestionFind(eid,sugid);if(!e||!s)return;dossierPopup('Konkreten nächsten Schritt anpassen',`<div class="dossier-grid">${dossierText('title','Was genau soll geschehen?',s.title,true)}${dossierField('assignedTo','Wer übernimmt den Schritt?',data.settings.activeUser||'Edmund','text',true)}${dossierField('due','Vorgeschlagener Termin (änderbar)',dossierSuggestedDue(s.dueDays),'date')}${dossierText('expectedResult','Woran erkennst du die Umsetzung?',s.rationale)}<p class="full">Der Termin ist ein Vorschlag. Erst mit „Übernehmen“ wird die Aufgabe angelegt und direkt mit diesem Chronikeintrag verknüpft.</p></div>`,async fd=>{const f=Object.fromEntries(fd),t=Dossier.addTask(data,{...f,participantIds:e.participantIds,sourceEntryKey:'entry:'+e.id,taskType:s.taskType,caseId:'',priority:'Normal'});s.status='übernommen';s.taskId=t.id;s.decidedAt=new Date().toISOString();await dossierSave();closeModal('dossierEditModal');dossierRefresh();});document.querySelector('#dossierEditModal [type=submit]').textContent='Übernehmen';}
async function dossierPin(eid){const e=data.journal.find(e=>e.id===eid);if(!e)return;e.pinnedFor=e.pinnedFor||[];e.pinHistory=e.pinHistory||[];const was=e.pinnedFor.includes(selectedStudentId);e.pinnedFor=was?e.pinnedFor.filter(s=>s!==selectedStudentId):[...e.pinnedFor,selectedStudentId];e.pinHistory.push({at:new Date().toISOString(),studentId:selectedStudentId,pinned:!was});await dossierSave();dossierRefresh();}
function dossierStep(key,type='Nächster Schritt'){
 const origin=dossierRecord(key),participantIds=origin?Dossier.ids(data,origin):[selectedStudentId];
 dossierPopup(type,`<div class="dossier-grid">${dossierText('title','Was soll geschehen?','',true)}${dossierField('assignedTo','Wer ist zuständig?','','text',true)}${dossierField('due','Bis wann / wann? (optional)','','date')}${dossierText('expectedResult','Wozu / welches Ziel?')}<p class="full">Verknüpft mit ${participantIds.length} Schülerakte(n). Ohne Datum erscheint der Schritt unter „Offen ohne Termin“.</p></div>`,async fd=>{const f=Object.fromEntries(fd);Dossier.addTask(data,{...f,participantIds,sourceEntryKey:key,taskType:type,caseId:'',priority:'Normal'});await dossierSave();closeModal('dossierEditModal');dossierRefresh();});
}
function dossierTask(tid){
 const t=data.tasks.find(t=>t.id===tid);if(!t)return;
 dossierPopup('Schritt bearbeiten',`<div class="dossier-grid">${dossierText('title','Was soll geschehen?',t.title,true)}${dossierField('assignedTo','Zuständigkeit',t.assignedTo||'','text',true)}${dossierField('due','Termin (optional)',t.due||'','date')}<label>Status<select class="field" name="status">${dossierOptions(['offen','in Bearbeitung','wartet auf Rückmeldung','erledigt','entfällt'],t.status||'offen')}</select></label>${dossierText('result','Was kam dabei heraus? / Grund für Entfall',t.result||'')}${dossierField('completedAt','Ergebnisdatum',t.completedAt||today(),'date')}<label><span><input type="checkbox" name="next"> Weiterer Schritt nötig</span></label>${t.assignmentReview?'<label><span><input type="checkbox" name="reviewed"> Zuständigkeit geprüft</span></label>':''}</div>`,async fd=>{const f=Object.fromEntries(fd);Dossier.setTask(data,t,{title:f.title,assignedTo:f.assignedTo,due:f.due,status:f.status,result:f.result,completedAt:f.completedAt},data.settings.activeUser||'SSA');if(fd.has('reviewed'))delete t.assignmentReview;await dossierSave();closeModal('dossierEditModal');if(selectedStudentId)dossierRefresh();if(fd.has('next'))dossierStep('task:'+t.id);});
}
function dossierAssessment(){const a=Dossier.currentAssessment(data,selectedStudentId);dossierPopup('Fachlichen Handlungsbedarf einschätzen',`<div class="dossier-grid"><label>Bewertung<select class="field" name="color">${Object.entries(dossierColors).map(([k,v])=>`<option value="${k}" ${a?.color===k?'selected':''}>${v}</option>`).join('')}</select></label>${dossierField('date','Bewertungsdatum',today(),'date',true)}${dossierField('author','Bewertende Person',data.settings.activeUser||'Edmund','text',true)}${dossierText('reason','Begründung','',true)}${dossierField('reviewDate','Erneute Einschätzung vorgesehen (optional)','','date')}<p>Eine Aufgabe wird nur über „Nächsten Schritt vereinbaren“ angelegt.</p></div>`,async fd=>{Dossier.assess(data,selectedStudentId,Object.fromEntries(fd));await dossierSave();closeModal('dossierEditModal');dossierRefresh();});}
ampelKind=function(sid){const a=Dossier.currentAssessment(data,sid);return a?{stufe:a.color,grund:a.reason,gruende:[],date:a.date}:{stufe:'grau',grund:'Noch nicht fachlich eingeschätzt',gruende:[]};};
function dossierMakePreview(pupils,year,classLeads={}){pendingYearChange=Dossier.preview(data,pupils,{year,classLeads,effectiveDate:year===data.settings.currentSchoolYear?today():year.slice(0,4)+'-08-01'});renderYearReview();openModal('yearReviewModal');}
function importStudents(event){previewStudentImport(event);}
function previewStudentImport(event){const file=event.target.files[0];event.target.value='';if(!file)return;if(file.size>5*1024*1024){appAlert('Datei ist größer als 5 MB.');return;}file.text().then(text=>{const p=parseStudentRows(text,file.name);dossierMakePreview(p.pupils,p.schoolYear,p.classLeads);}).catch(err=>appAlert(err.message));}
function dossierIndividualYear(studentId){
 const s=data.students.find(function(x){return x.id===studentId});if(!s)return;
 const next=nextSchoolYear(data.settings.currentSchoolYear),suggested=Dossier.nextClass(s.className)||s.className;
 dossierPopup('Klasse für einzelne:n Schüler:in ändern',`<div class="notice">${DE(s.first+' '+s.last)} · bisher ${DE(s.className)} · stabile Schüler-ID ${DE(s.id)}. Die vollständige Akte bleibt erhalten. Frühere Einträge behalten ihre damalige Klasse.</div><div class="dossier-grid"><label>Zielschuljahr<select class="field" name="targetYear"><option value="${DE(data.settings.currentSchoolYear)}">Im laufenden Schuljahr ${DE(data.settings.currentSchoolYear)}</option><option value="${DE(next)}">Zum nächsten Schuljahr ${DE(next)}</option></select></label>${dossierField('className','Neue Klasse',suggested,true)}<label>Grund<select class="field" name="reason">${dossierOptions(['Parallelklassenwechsel','Reguläre Versetzung','Wiederholung','Überspringen','Geprüfte Klassenzuordnung'],'Parallelklassenwechsel')}</select></label><p class="full">Die Änderung wird zunächst nur als Vorschau vorbereitet und erst nach deiner Prüfung gespeichert.</p></div>`,async fd=>{
  const f=Object.fromEntries(fd),year=f.targetYear,planDate=year===data.settings.currentSchoolYear?today():year.slice(0,4)+'-08-01';
  dossierMakePreview([{givenId:s.id,first:s.first,last:s.last,className:f.className.trim(),schoolYear:year}],year);
  if(pendingYearChange?.rows[0]){pendingYearChange.effectiveDate=planDate;pendingYearChange.rows[0].confirmed=false;pendingYearChange.rows[0].reason=f.reason;}
  closeModal('dossierEditModal');renderYearReview();openModal('yearReviewModal');
 });
}
function dossierManualYear(){
 const next=nextSchoolYear(data.settings.currentSchoolYear);
 const pupils=data.students.filter(s=>s.active!==false).map(s=>({givenId:s.id,first:s.first,last:s.last,className:Dossier.nextClass(s.className)||s.className,schoolYear:next}));
 dossierMakePreview(pupils,next);
 for(const r of pendingYearChange.rows){const old=data.students.find(s=>s.id===r.studentId);r.confirmed=false;r.reason=Dossier.nextClass(old?.className||'')?'Reguläre Versetzung':'Schulabgang / Schulwechsel';}
 renderYearReview();
}
function dossierYearAction(i,value){const r=pendingYearChange.rows[i];if(value==='new'){r.studentId='';r.action='new';}else if(['skip','keep','leave','transfer'].includes(value)){r.action=value;}else if(value){r.studentId=value;r.action='update';}else{r.action='review';}r.confirmed=false;renderYearReview();}
function renderYearReview(){const p=pendingYearChange;if(!p)return;
 const summary=document.getElementById('yearReviewSummary');summary.style.display='block';summary.innerHTML=`<div class="dossier-grid">${dossierField('year','Zielschuljahr',p.schoolYear)}${dossierField('effectiveDate','Klassenzuordnung gültig ab',p.effectiveDate,'date',true)}</div><p>Jede Zeile bleibt korrigierbar. Namensähnlichkeit ist nur ein Vorschlag. Fehlende Kinder bleiben aktiv, sofern du keinen Abgang bestätigst. Zuständigkeiten und Ampelbewertungen bleiben bestehen.</p><p>${p.rows.filter(r=>!r.confirmed).length} Zeilen noch zu prüfen.</p>`;
 summary.insertAdjacentHTML('beforeend','<datalist id="dossierAllStudents">'+data.students.map(s=>'<option value="'+DE(s.last+', '+s.first+' · '+s.id)+'"></option>').join('')+'</datalist>');
 summary.querySelector('[name=year]').onchange=e=>{p.schoolYear=e.target.value;for(const r of p.rows)if(r.pupil)r.pupil.schoolYear=p.schoolYear;};summary.querySelector('[name=effectiveDate]').onchange=e=>p.effectiveDate=e.target.value;
 document.querySelector('#yearReviewModal .dialog').classList.add('wide');document.querySelector('#yearReviewModal thead').innerHTML='<tr><th>Kind / Zuordnung</th><th>Bisher</th><th>Neue Klasse / Grund</th><th>Geprüft</th></tr>';
 document.getElementById('yearReviewTable').innerHTML=p.rows.map((r,i)=>{
 const s=data.students.find(s=>s.id===r.studentId),name=r.pupil?(r.pupil.last+', '+r.pupil.first):s?.last+', '+s?.first;const chosen=r.action==='update'?r.studentId:r.action;
 const candidates=[...new Set([r.studentId,...r.candidates||[]])].filter(Boolean),ordered=data.students.filter(s=>candidates.includes(s.id)).sort((a,b)=>a.last.localeCompare(b.last));
 return `<tr class="dossier-review"><td><strong>${DE(name)}</strong><br><small>${r.missing?'Fehlt in der Liste':r.pupil.givenId?'Kennung: '+DE(r.pupil.givenId):'Ohne verlässliche Kennung: manuell zuordnen'}</small><select aria-label="Akte zuordnen" onchange="dossierYearAction(${i},this.value)"><option value="review">Bitte prüfen …</option>${r.pupil?'<option value="new" '+(chosen==='new'?'selected':'')+'>Geprüfte Neuaufnahme</option>':''}<option value="${r.missing?'keep':'skip'}" ${['keep','skip'].includes(chosen)?'selected':''}>Unverändert lassen</option>${r.studentId?'<option value="leave" '+(chosen==='leave'?'selected':'')+'>Bestätigter Schulabgang</option><option value="transfer" '+(chosen==='transfer'?'selected':'')+'>Bestätigter Schulwechsel</option>':''}${r.pupil?ordered.map(s=>`<option value="${DE(s.id)}" ${chosen===s.id?'selected':''}>${DE(s.last+', '+s.first+' · '+s.className+' · '+s.id)}${s.active===false?' (archiviert)':''}</option>`).join(''):''}</select>${r.pupil?`<input list="dossierAllStudents" placeholder="Andere Akte suchen …" aria-label="Andere Akte suchen" onchange="dossierOtherStudent(${i},this.value)">`:''}</td><td>${DE(s?.className||'–')}<br>${DE(s?.schoolYear||'')}<br>${s?DE(s.id):''}</td><td>${r.pupil?`<input aria-label="Neue Klasse" value="${DE(r.pupil.className)}" onchange="pendingYearChange.rows[${i}].pupil.className=this.value.trim();pendingYearChange.rows[${i}].confirmed=false;renderYearReview()"><input aria-label="Neue Klassenleitung" placeholder="Neue Klassenleitung" value="${DE(p.classLeads[r.pupil.className]||'')}" onchange="pendingYearChange.classLeads[pendingYearChange.rows[${i}].pupil.className]=this.value.trim()"><select aria-label="Art des Wechsels" onchange="pendingYearChange.rows[${i}].reason=this.value">${dossierOptions(['Geprüfte Klassenzuordnung','Reguläre Versetzung','Wiederholung','Überspringen','Parallelklassenwechsel','Schulkindergarten → Klasse 1','Neuaufnahme / Rückkehr'],r.reason||'Geprüfte Klassenzuordnung')}</select>`:'Keine automatische Archivierung'}</td><td><label><input type="checkbox" ${r.confirmed?'checked':''} onchange="pendingYearChange.rows[${i}].confirmed=this.checked"> Geprüft</label></td></tr>`;
 }).join('');document.getElementById('applyYearButton').textContent='Geprüfte Änderungen übernehmen';
}
async function applyYearChange(){if(!pendingYearChange)return;const p=pendingYearChange;const errors=Dossier.validate(data,p);if(errors.length){appAlert(errors.join('\n'));return;}if(!await appConfirm('Geprüfte Änderungen übernehmen? Vorher wird eine vollständige Sicherung einschließlich Dokumenten erstellt.'))return;if(!await exportCompleteBackup('Vor Schuljahreswechsel',false))return;
 const before=data,next=structuredClone(data),plan=structuredClone(p);Dossier.apply(next,plan);data=next;try{await persistState();}catch(err){data=before;appAlert('Nicht gespeichert: '+String(err));return;}pendingYearChange=null;renderAll();closeModal('yearReviewModal');go('students');toast('Bestehende Akten fortgeführt. Offene Aufgaben bleiben sichtbar.');}
// Open tasks remain visible even after confirmed departure.
aufgabeArchiviert=function(t){return false;};
toggleStudentStatus=async function(){const s=data.students.find(s=>s.id===selectedStudentId);if(!s)return;if(s.active!==false){dossierPopup('Schulabgang bestätigen',`<div class="dossier-grid"><label>Grund<select name="reason" class="field">${dossierOptions(['Bestätigter Schulabgang','Bestätigter Schulwechsel'],'')}</select></label>${dossierField('date','Gültig ab',today(),'date',true)}<p class="full">Die gesamte Akte bleibt erhalten. ${Dossier.work(data,s.id).filter(t=>!t.done).length} offene Aufgaben bleiben zur Prüfung sichtbar.</p></div>`,async fd=>{Dossier.archive(data,s.id,fd.get('date'),fd.get('reason'));await dossierSave();closeModal('dossierEditModal');dossierRefresh();});}else{dossierMakePreview([{givenId:s.id,first:s.first,last:s.last,className:s.className,schoolYear:data.settings.currentSchoolYear}],data.settings.currentSchoolYear);}};
const legacyRenderTasks=renderTasks;
renderTasks=function(){const list=document.getElementById('taskList');list.innerHTML=`<div class="dossier-toolbar"><button class="btn" onclick="dossierCalendar()">Kalender / Aufgabenboard</button></div>`+data.tasks.slice().sort((a,b)=>Number(a.done)-Number(b.done)||String(a.due||'9999').localeCompare(String(b.due||'9999'))).map(t=>`<div class="row ${t.done?'taskdone':''}"><div class="grow"><strong>${DE(t.title)}</strong><span class="subtle">${DE(t.due?fmt(t.due):'Ohne Termin')} · ${DE(t.status||'offen')} · ${DE(t.assignedTo||'nicht festgelegt')}</span><span>${Dossier.ids(data,t).map(sid=>{const s=data.students.find(s=>s.id===sid);return `<button class="linkbutton" onclick="showStudent('${DE(sid)}')">${DE(s?s.first+' '+s.last:'Unklare Zuordnung')}</button>`;}).join(' · ')}</span>${t.assignmentReview?`<p class="notice warning">${DE(t.assignmentReview)}</p>`:''}${t.instructions?`<details><summary>Anleitung</summary><p>${DE(t.instructions)}</p></details>`:''}${t.result?'<p>'+DE(t.result)+'</p>':''}</div><div class="actions">${t.done?`<button class="btn" onclick="reopenTask('${DE(t.id)}')">Wieder öffnen</button>`:`<button class="btn primary" onclick="openTaskComplete('${DE(t.id)}')">Erledigt markieren</button>`}<button class="btn" onclick="dossierTask('${DE(t.id)}')">Bearbeiten</button><button class="btn danger" onclick="dossierDeleteTask('${DE(t.id)}')">Entfernen</button></div></div>`).join('');};
async function dossierDeleteTask(tid){
 const t=data.tasks.find(t=>t.id===tid);if(!t||!await appConfirm(`Aufgabe „${t.title}“ wirklich entfernen? Dieser Schritt kann nicht rückgängig gemacht werden.`))return;
 if(t.recurrence){data.settings.dismissedRecurringTaskKeys=data.settings.dismissedRecurringTaskKeys||[];data.settings.dismissedRecurringTaskKeys.push(t.recurrence+':'+t.due);}
 const studentId=Dossier.ids(data,t)[0]||'';data.tasks=data.tasks.filter(x=>x.id!==tid);logChange('Aufgabe entfernt: '+t.title,t.id,studentId,data.settings.activeUser||'SSA');await dossierSave();toast('Aufgabe wurde entfernt.');
}
function dossierCalendar(){const tasks=data.tasks.filter(t=>!t.done).sort((a,b)=>String(a.due||'9999').localeCompare(String(b.due||'9999')));dossierPopup('Termine und Aufgabenboard',`<p>Dieselben Aufgaben wie in der Chronologie. Alle Schuljahre und auch bestätigte Abgänge sind enthalten.</p><div class="dossier-grid">${['offen','in Bearbeitung','wartet auf Rückmeldung'].map(st=>`<section><h3>${DE(st)}</h3>${tasks.filter(t=>(t.status||'offen')===st).map(t=>`<p><button type="button" class="btn" onclick="dossierTask('${DE(t.id)}')">${DE(t.title)}</button><br>${DE(t.due?fmt(t.due):'ohne Termin')} · ${DE(t.assignedTo||'')}</p>`).join('')}</section>`).join('')}</div><h3>Kalender nach Datum</h3>${tasks.filter(t=>t.due).map(t=>`<p>${DE(fmt(t.due))} · <button type="button" class="linkbutton" onclick="dossierTask('${DE(t.id)}')">${DE(t.title)}</button></p>`).join('')}`,async()=>closeModal('dossierEditModal'));}
// Preserve existing recurrence logic for recurring organizational tasks.
const dossierOriginalTask=dossierTask;
dossierTask=function(tid){const t=data.tasks.find(t=>t.id===tid);if(t?.recurrence){openTaskComplete(tid);return;}dossierOriginalTask(tid);};
statDaten=function(){const d=legacyStatDaten();for(const e of Dossier.journalStats(data,'',statKlasse()).filter(e=>imZeitraum(e,d.z))){const row={...e,caseId:data.cases.find(c=>c.studentId===e.participantIds[0])?.id||'',reason:e.type,level:e.participantIds.length>1?'Gruppe':'Einzel'};if(e.participantIds.length>1)d.gruppen.push(row);else d.kontakte.push(row);}return d;};
// All regular entry paths enter the same editor. No case selection is needed.
verlaufOeffnen=function(sid='',type='',origin=null){if(sid)selectedStudentId=sid;dossierEntry(type==='Rückmeldung'?'response':'event',origin?'legacy:'+origin.id:'');};
openClassActivity=function(className=''){dossierEntry('event','',data.students.filter(s=>s.active!==false&&s.className===className).map(s=>s.id));const f=document.getElementById('dossierEditForm');f.elements.type.value='Sozialtraining / Klassentraining / Kleingruppenangebot';};
const oldGroupSubmit=document.getElementById('groupTalkForm').onsubmit;
document.getElementById('groupTalkForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),f=Object.fromEntries(fd),participantIds=fd.getAll('participantIds');const entry=Dossier.addEntry(data,{...f,participantIds,type:'Gruppengespräch / Konfliktklärung / Vermittlung',title:f.type,content:[f.note,f.result,f.individualNotes?'Früherer unzugeordneter Hinweis: '+f.individualNotes:''].filter(Boolean).join('\n')||f.type});if(f.due)Dossier.addTask(data,{title:'Rückmeldung: '+f.type,assignedTo:f.responsible||'Zuständigkeit prüfen',due:f.due,participantIds,sourceEntryKey:'entry:'+entry.id});await dossierSave();closeModal('groupTalkModal');showStudent(participantIds[0]);};
// The original task completion entry point also opens the shared status editor.
const oldTaskComplete=openTaskComplete;
openTaskComplete=function(tid){const t=data.tasks.find(t=>t.id===tid);if(t?.recurrence)return oldTaskComplete(tid);dossierOriginalTask(tid);};
// Expose documentation from Settings and preserve the familiar desktop application.
const help=document.createElement('div');help.className='card';help.innerHTML='<h3>Chronologie und Schuljahreswechsel</h3><p>Ein Kind, eine dauerhafte Akte. Anleitung zur neuen Bedienung, zu Import und Sicherung.</p><button class="btn" onclick="dossierHandbook()">Handbuch öffnen</button>';document.getElementById('settings').append(help);
function dossierHandbook(){dossierPopup('Handbuch · Version 0.11.3',`<p>Öffne unter Schüler:innen ein Kind. „Ereignis / Gespräch eintragen“ dokumentiert den Inhalt; „Information hinzufügen“ reicht für Zusatzwissen wie Ergotherapie. Die Akte ist automatisch zugeordnet.</p><p>Weitere Kinder wählst du unter „Zuordnung prüfen“. Nur tatsächlich Teilnehmende markieren. Gemeinsame Inhalte werden einmal gespeichert; individuelle Ergänzungen erscheinen nur beim ausgewählten Kind.</p><p>Die Zeitleiste verläuft von früher nach später und öffnet bei „Heute“. Geplante Einträge sind gestrichelt und bleiben unbestätigt, bis du sie ausdrücklich bearbeitest. Aufgaben ohne Termin stehen unten. Überfällige Aufgaben sind bei Heute verlinkt.</p><p>Am Eintrag kannst du mehrere nächste Schritte, Rückmeldungen und Überprüfungen verknüpfen. Zuständigkeiten und Fristen bestimmst du selbst. Statusänderungen und Verschiebungen bleiben nachvollziehbar. Aufgabenliste, Kalender und Aufgabenboard zeigen dieselben Datensätze.</p><p>Die fachliche Ampel wird mit Begründung, Datum und Person eingetragen. Berechnete Fehlzeitenhinweise bleiben davon getrennt. Ein Schuljahreswechsel ändert die Bewertung nicht.</p><p>Unter Schüler:innen kannst du eine CSV prüfen oder „Wechsel ohne Import vorbereiten“ wählen. Korrigiere Aktenzuordnung, Klasse, Klassenleitung, Wechselart und Gültig-ab-Datum. Namensgleichheit ist kein automatischer Treffer. Verlässliche externe Kennungen werden nach Prüfung gespeichert. Ohne Kennung verwendest du künftig die exportierte Klassenliste mit der stabilen Schüler-ID.</p><p>Fehlende Kinder bleiben unverändert. Bestätigte Abgänge werden einzeln archiviert; offene Aufgaben bleiben sichtbar. Vor dem Wechsel wird eine Gesamtsicherung erstellt. Vergangene Klassen bleiben an den Einträgen erhalten. Unbekannte historische Daten werden als unbekannt angezeigt.</p><p>Beim ersten Öffnen einer älteren Version wird vor der Datenanpassung eine verschlüsselte Sicherung im Sicherungsordner des Datentresors erstellt. Der Schuljahresfilter blendet nur aus. Dokumente verbleiben in der bestehenden Akte.</p><p>Alte, keinem Kind verlässlich zugeordnete Einträge müssen manuell geprüft werden. Aus Freitext entstehen keine automatischen Diagnosen, Aufgaben oder Personenzuordnungen.</p>`,async()=>closeModal('dossierEditModal'));}

openGroupTalk=function(){selectedStudentId='';dossierEntry('event');document.getElementById('dossierEditForm').elements.type.value='Gruppengespräch / Konfliktklärung / Vermittlung';};

function dossierOtherStudent(i,value){const s=data.students.find(s=>s.last+', '+s.first+' · '+s.id===value);if(s)dossierYearAction(i,s.id);else appAlert('Bitte eine Akte aus den Suchvorschlägen auswählen.');}

function dossierReportSelection(fd){
 const sid=selectedStudentId,s=data.students.find(x=>x.id===sid),from=fd.get('from'),to=fd.get('to'),kind=fd.get('kind');if(!s)throw Error('Schülerakte fehlt.');if(from&&to&&from>to)throw Error('Der Beginn liegt nach dem Ende.');
 const events=Dossier.timeline(data,sid,legacyStudentEvents(sid)).filter(e=>e.date&&(!from||e.date>=from)&&(!to||e.date<=to));
 const categories={Gespräche:['talk','parent','external','training'],Fehlzeiten:['absence'],Dokumente:['document'],Aufgaben:['task']};
 return {s,from,to,selected:kind==='Alle'?events:events.filter(e=>categories[kind]?.includes(dossierCategory(e))),privacy:fd.has('withoutPrivate')};
}
function dossierReport(){dossierPopup('Verlaufsbericht und Druckansicht',`<div class="dossier-grid">${dossierField('from','Von',today().slice(0,4)+'-01-01','date')}${dossierField('to','Bis',today(),'date')}<label>Einträge<select class="field" name="kind">${dossierOptions(['Alle','Gespräche','Fehlzeiten','Dokumente','Aufgaben'], 'Alle')}</select></label><button type="button" class="btn" onclick="dossierLastSixMonths()">Letzte 6 Monate</button><label><input type="checkbox" name="withoutPrivate" checked> Vertrauliche individuelle Notizen ausblenden</label><p class="full">Chronologischer Auszug aus den gespeicherten Einträgen. Prüfe Inhalt und Empfänger vor dem Weitergeben.</p><button type="button" class="btn full" onclick="dossierReportWord()">Als Word-Datei (.docx) herunterladen</button></div>`,async fd=>{const {s,from,to,selected,privacy}=dossierReportSelection(fd);const body=`<p><strong>${DE(s.first+' '+s.last)}</strong> · ${DE(s.schoolYear+' · Klasse '+s.className)} · Zeitraum ${DE(from||'Beginn')} bis ${DE(to||'heute')}</p><p>${selected.length} Einträge. Historische Klassenzuordnungen stehen beim jeweiligen Eintrag.</p>${selected.map(e=>`<section style="break-inside:avoid;border-top:1px solid #b5c7ce;padding:12px 0"><strong>${DE(fmt(e.date))} · ${e.sourceEntryKey?'Folgeaktion · ':''}${DE(e.eventKind||'Eintrag')} · ${DE(e.title||'')}</strong><p>${DE(e.content||'')}</p>${!privacy&&e.individualNote?'<p>Individuelle Notiz: '+DE(e.individualNote)+'</p>':''}<small>${DE(e.context?.schoolYear||'')} · ${DE(e.context?.className||'Klasse unbekannt')}</small></section>`).join('')||'<p>Keine Einträge für die Auswahl.</p>'}`;closeModal('dossierEditModal');printDocument('Verlaufsbericht · '+s.first+' '+s.last,body);});document.querySelector('#dossierEditModal [type=submit]').textContent='Druckansicht / PDF öffnen';}
function dossierLastSixMonths(){const form=document.getElementById('dossierEditForm'),date=new Date(today()+'T12:00:00');date.setMonth(date.getMonth()-6);form.elements.from.value=date.toISOString().slice(0,10);form.elements.to.value=today();}
function dossierReportWord(){try{const {s,from,to,selected,privacy}=dossierReportSelection(new FormData(document.getElementById('dossierEditForm')));const lines=[{text:s.first+' '+s.last+' · '+s.schoolYear+' · Klasse '+s.className,bold:true},'Zeitraum: '+(from||'Beginn')+' bis '+(to||'heute'),'Chronologischer Auszug · '+selected.length+' Einträge',''];for(const e of selected){lines.push({text:fmt(e.date)+' · '+(e.sourceEntryKey?'Folgeaktion · ':'')+(e.eventKind||'Eintrag')+' · '+(e.title||''),bold:true},String(e.content||''),[e.context?.schoolYear,e.context?.className&&'damals Klasse '+e.context.className].filter(Boolean).join(' · '));if(!privacy&&e.individualNote)lines.push('Individuelle Notiz: '+e.individualNote);lines.push('');}const bytes=DossierDocx.build('SSA-Cockpit · Verlaufsbericht',lines),name='SSA-Verlaufsbericht-'+(s.id||'Akte')+'-'+today()+'.docx';download(name,bytes,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');closeModal('dossierEditModal');toast('Word-Datei wurde heruntergeladen. Inhalt vor der Weitergabe prüfen.');}catch(err){appAlert(err.message||String(err));}}
const dossierUXStyle=document.createElement('style');dossierUXStyle.textContent='.dossier-tags{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}.dossier-docs-present{background:#dcf4e4!important;border-color:#55a87c!important;color:#145932!important}.dossier-milestone{border:2px solid #bf8d27!important;background:#fff9e9!important}.dossier-rating{margin:8px 0;padding:10px;background:#edf7f1;border-radius:8px}.modal.maximized{padding:0!important}.modal.maximized>.dialog{width:100vw!important;max-width:none!important;height:100vh!important;max-height:none!important;border-radius:0!important;display:flex;flex-direction:column}.modal.maximized .dialogbody{overflow:auto;flex:1}.modal.maximized .dialoghead{flex:none}.modal.maximized .dialogfoot{flex:none}';document.head.append(dossierUXStyle);
function dossierMaximizeButtons(){for(const modal of document.querySelectorAll('.modal')){const head=modal.querySelector('.dialoghead');if(!head||head.querySelector('.dossier-maximize'))continue;const button=document.createElement('button');button.type='button';button.className='btn dossier-maximize';button.textContent='⛶ Vollbild';button.title='Fenster vergrößern oder verkleinern';button.onclick=()=>{modal.classList.toggle('maximized');button.textContent=modal.classList.contains('maximized')?'⛶ Verkleinern':'⛶ Vollbild'};head.insertBefore(button,head.querySelector('.close'));}}
dossierMaximizeButtons();new MutationObserver(dossierMaximizeButtons).observe(document.body,{childList:true,subtree:true});

