const dossierTaskControlsStateful=dossierTaskControls;
dossierTaskControls=function(){let html=dossierTaskControlsStateful();html=html.replace('<option value="alle">Alle Zuständigkeiten</option>','<option value="alle" '+(dossierTaskView.assignee==='alle'?'selected':'')+'>Alle Zuständigkeiten</option>');html=html.replace('<option value="mir">Mir zugewiesen</option>','<option value="mir" '+(dossierTaskView.assignee==='mir'?'selected':'')+'>Mir zugewiesen</option>');html=html.replace('<option value="unzugeordnet">Nicht zugeordnet</option>','<option value="unzugeordnet" '+(dossierTaskView.assignee==='unzugeordnet'?'selected':'')+'>Nicht zugeordnet</option>');html=html.replace('<option value="alle">Alle Termine</option>','<option value="alle" '+(dossierTaskView.due==='alle'?'selected':'')+'>Alle Termine</option>');html=html.replace('<option value="ueberfaellig">Überfällig</option>','<option value="ueberfaellig" '+(dossierTaskView.due==='ueberfaellig'?'selected':'')+'>Überfällig</option>');html=html.replace('<option value="heute">Heute</option>','<option value="heute" '+(dossierTaskView.due==='heute'?'selected':'')+'>Heute</option>');html=html.replace('<option value="ohne">Ohne Termin</option>','<option value="ohne" '+(dossierTaskView.due==='ohne'?'selected':'')+'>Ohne Termin</option>');return html;};
dossierRenderTaskList=function(){const list=document.getElementById('taskList');if(!list)return;const active=document.activeElement?.id==='dossierTaskSearch',oldValue=active?document.activeElement.value:'',start=active?document.activeElement.selectionStart:null,end=active?document.activeElement.selectionEnd:null;const rows=data.tasks.slice().sort((a,b)=>Number(a.done)-Number(b.done)||String(a.due||'9999').localeCompare(String(b.due||'9999'))).filter(dossierTaskMatches);list.innerHTML=dossierTaskControls()+'<p class="subtle">'+rows.length+' von '+data.tasks.length+' Aufgaben sichtbar.</p>'+rows.map(dossierTaskRow).join('');if(active){const input=document.getElementById('dossierTaskSearch');if(input){input.focus();input.value=oldValue;try{input.setSelectionRange(start,end);}catch{}}}};
dossierWebUntisReview=function(){const signals=data.schoolSignals||[],open=signals.filter(s=>String(s.reviewStatus||'').toLowerCase().includes('nicht')||s.unresolvedNames?.length||s.classChanges?.length),body='<div class="notice"><strong>'+signals.length+' WebUntis-Signale gespeichert</strong> · '+open.length+' benötigen noch Prüfung.</div><table class="table dossier-review"><thead><tr><th>Datum</th><th>Schüler:in</th><th>Fehlzeiten</th><th>Status</th></tr></thead><tbody>'+signals.slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).map(s=>{const st=data.students.find(x=>x.id===s.studentId);const name=st?st.first+' '+st.last:(s.studentName||s.name||s.unresolvedNames?.join(', ')||'Zuordnung prüfen');const abs=s.absences??s.absenceDays??s.unexcused??'';return '<tr><td>'+DE(s.date||s.period||'unbekannt')+'</td><td>'+DE(name)+'</td><td>'+DE(String(abs))+'</td><td>'+DE(s.reviewStatus||'Noch nicht geprüft')+'</td></tr>';}).join('')+'</tbody></table><p>Fehlende Importzeilen archivieren keine Akte automatisch.</p>';dossierPopup('WebUntis · Importprüfung',body,async()=>closeModal('dossierEditModal'));};
openAttachment=async function(id){const a=await getAttachment(id);if(!a)return;const mime=a.mimeType||'application/octet-stream';if(!/^application\/(pdf)|^image\//i.test(mime)){return downloadAttachment(id);}const url=URL.createObjectURL(new Blob([new Uint8Array(a.bytes)],{type:mime}));const wrap=document.createElement('div');wrap.className='modal open dossier-preview-modal';wrap.innerHTML='<div class="dialog wide"><div class="dialoghead"><h2>'+DE(a.name||'Dokument')+'</h2><button class="close" type="button">×</button></div><div class="dialogbody" style="padding:0;min-height:70vh"><iframe title="Dokumentvorschau" style="width:100%;height:70vh;border:0"></iframe></div></div>';document.body.append(wrap);const frame=wrap.querySelector('iframe');frame.src=url;wrap.querySelector('.close').onclick=()=>{URL.revokeObjectURL(url);wrap.remove();};};

/* ---------- Chronik: Kacheln ordnen, vollständig löschen, Vorschläge verwalten ---------- */
(function(){
 const baseTimeline=typeof Dossier!=='undefined'&&Dossier.timeline;
 if(baseTimeline&&!Dossier.timeline.__dossierOrder){
  const ordered=function(state,sid,legacy){
   const rows=(baseTimeline.call(this,state,sid,legacy)||[]).filter(function(row){return !(state.settings&&state.settings.timelineHidden&&state.settings.timelineHidden[sid]||[]).includes(row.key)}),order=state.settings&&state.settings.timelineOrder&&state.settings.timelineOrder[sid]||[],rank=new Map(order.map(function(key,i){return [key,i]}));
   return rows.slice().sort(function(a,b){const ar=rank.has(a.key)?rank.get(a.key):Number.MAX_SAFE_INTEGER,br=rank.has(b.key)?rank.get(b.key):Number.MAX_SAFE_INTEGER;return ar-br||String(a.date||'9999').localeCompare(String(b.date||'9999'))||String(a.key).localeCompare(String(b.key));});
  };
  ordered.__dossierOrder=true;Dossier.timeline=ordered;
 }
})();
function dossierTimelineOrder(sid){
 const rows=Dossier.timeline(data,sid,legacyStudentEvents(sid))||[],keys=rows.map(function(e){return e.key}),saved=data.settings&&data.settings.timelineOrder&&data.settings.timelineOrder[sid]||[],valid=saved.filter(function(k){return keys.includes(k)});return valid.concat(keys.filter(function(k){return !valid.includes(k)}));
}
function dossierDragStart(event,key){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',key);event.currentTarget.setAttribute('aria-grabbed','true');event.currentTarget.classList.add('dossier-dragging');}
function dossierDragEnd(event){event.currentTarget.removeAttribute('aria-grabbed');event.currentTarget.classList.remove('dossier-dragging');}
function dossierDragOver(event,card){event.preventDefault();card.classList.add('dossier-drop-target');if(event.dataTransfer)event.dataTransfer.dropEffect='move';}
function dossierDragLeave(event,card){if(!card.contains(event.relatedTarget))card.classList.remove('dossier-drop-target');}
document.addEventListener('dragend',function(event){const card=event.target.closest?.('.dossier-card');if(card)dossierDragEnd({currentTarget:card});});
async function dossierDrop(event,targetKey){
 event.preventDefault();event.currentTarget.classList.remove('dossier-drop-target');const source=event.dataTransfer.getData('text/plain');if(!source||source===targetKey||!selectedStudentId)return;
 const order=dossierTimelineOrder(selectedStudentId),from=order.indexOf(source),to=order.indexOf(targetKey);if(from<0||to<0)return;
 order.splice(from,1);order.splice(to,0,source);data.settings.timelineOrder=data.settings.timelineOrder||{};data.settings.timelineOrder[selectedStudentId]=order;
 await dossierSave();toast('Chronik-Kachel wurde neu eingeordnet.');dossierRefresh();
}
async function dossierMoveCard(key,delta){
 if(!selectedStudentId)return;
 const order=dossierTimelineOrder(selectedStudentId),from=order.indexOf(key),to=from+Number(delta||0);if(from<0||to<0||to>=order.length)return;
 order.splice(from,1);order.splice(to,0,key);data.settings.timelineOrder=data.settings.timelineOrder||{};data.settings.timelineOrder[selectedStudentId]=order;
 await dossierSave();dossierRefresh();toast('Chronik-Kachel wurde neu eingeordnet.');
}
function dossierHideCard(key){if(!selectedStudentId)return;data.settings.timelineHidden=data.settings.timelineHidden||{};data.settings.timelineHidden[selectedStudentId]=data.settings.timelineHidden[selectedStudentId]||[];if(!data.settings.timelineHidden[selectedStudentId].includes(key))data.settings.timelineHidden[selectedStudentId].push(key);void dossierSave().then(function(){dossierRefresh();toast('Kachel wurde aus dieser Chronik ausgeblendet. Die zugrunde liegenden Daten bleiben erhalten.');});}
async function dossierDeleteEntry(eid){
 const e=data.journal.find(function(x){return x.id===eid});if(!e||!selectedStudentId)return;
 const linkedTasks=data.tasks.filter(function(t){return t.sourceEntryKey==='entry:'+eid}).length,linkedResponses=data.journal.filter(function(r){return r.sourceEntryKey==='entry:'+eid}).length;
 if(!await appConfirm('Diesen Chronikeintrag vollständig löschen?'+(linkedTasks||linkedResponses?'\n\nDabei werden auch '+linkedTasks+' verknüpfte Aufgabe(n) und '+linkedResponses+' Folge-Rückmeldung(en) gelöscht.':'')+'\nAnhänge bleiben in der Schülerakte erhalten.'))return;
 data.journal=data.journal.filter(function(x){return x.id!==eid&&x.sourceEntryKey!=='entry:'+eid});
 data.tasks=data.tasks.filter(function(t){return t.sourceEntryKey!=='entry:'+eid});
 data.documentEvents.forEach(function(d){if(d.sourceEntryKey==='entry:'+eid)d.sourceEntryKey='';});
 if(data.settings.timelineOrder&&data.settings.timelineOrder[selectedStudentId])data.settings.timelineOrder[selectedStudentId]=data.settings.timelineOrder[selectedStudentId].filter(function(k){return k!=='entry:'+eid});
 logChange('Chronikeintrag vollständig gelöscht',eid,selectedStudentId,data.settings.activeUser||'SSA');await dossierSave();dossierRefresh();toast('Chronikeintrag und direkt verknüpfte Folgeaktionen wurden gelöscht. Anhänge bleiben erhalten.');
}
